import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import { GLUE, assertGlueLoadsCrate, glueProblems } from "../scripts/check-generated-module.mjs";

// What ubrn 0.29.3-1 renders for the one component in the `bindings` crate,
// trimmed to the lines that matter.
const LOADED = {
  "src/index.tsx": `// Generated by uniffi-bindgen-react-native
import installer from './NativeKaleidoswapSwapSdk';

// Export the generated bindings to the app.
export * from './generated/kaleidorg_swap_sdk';

import * as kaleidorg_swap_sdk from './generated/kaleidorg_swap_sdk';

let initialized = false;
if (!initialized) {
  kaleidorg_swap_sdk.default.initialize();
  initialized = true;
}

export async function uniffiInitAsync() {
  // NOOP.
}

export default {
  kaleidorg_swap_sdk,
};
`,
  "cpp/kaleidoswap-swap-sdk.cpp": `// Generated by uniffi-bindgen-react-native
#include "kaleidoswap-swap-sdk.h"
#include "generated/kaleidorg_swap_sdk.hpp"

namespace kaleidoswapswapsdk {
	using namespace facebook;

	uint8_t installRustCrate(jsi::Runtime &runtime, std::shared_ptr<react::CallInvoker> callInvoker) {
		NativeKaleidorgSwapSdk::registerModule(runtime, callInvoker);
		return true;
	}
}
`,
  "android/CMakeLists.txt": `add_library(kaleidoswap-swap-sdk            SHARED
    ../cpp/kaleidoswap-swap-sdk.cpp
    ../cpp/generated/kaleidorg_swap_sdk.cpp
    cpp-adapter.cpp
)
`,
};

// What 0.11.0 shipped: the same templates rendered for zero components.
const EMPTY = {
  "src/index.tsx": `// Generated by uniffi-bindgen-react-native
import installer from './NativeKaleidoswapSwapSdk';

// Export the generated bindings to the app.

let initialized = false;
if (!initialized) {
  initialized = true;
}

export async function uniffiInitAsync() {
  // NOOP.
}

export default {
};
`,
  "cpp/kaleidoswap-swap-sdk.cpp": `// Generated by uniffi-bindgen-react-native
#include "kaleidoswap-swap-sdk.h"

namespace kaleidoswapswapsdk {
	using namespace facebook;

	uint8_t installRustCrate(jsi::Runtime &runtime, std::shared_ptr<react::CallInvoker> callInvoker) {
		return true;
	}
}
`,
  "android/CMakeLists.txt": `add_library(kaleidoswap-swap-sdk            SHARED
    ../cpp/kaleidoswap-swap-sdk.cpp
    cpp-adapter.cpp
)
`,
};

test("the checks cover exactly the files ubrn renders from the component list", () => {
  assert.deepEqual(Object.keys(GLUE).sort(), Object.keys(LOADED).sort());
});

test("accepts glue generated for the crate", () => {
  for (const [path, source] of Object.entries(LOADED)) {
    assert.deepEqual(glueProblems(path, source), [], path);
  }
  assert.doesNotThrow(() => assertGlueLoadsCrate((path) => LOADED[path]));
});

test("refuses the 0.11.0 entry, which exports no bindings and initializes none", () => {
  assert.deepEqual(glueProblems("src/index.tsx", EMPTY["src/index.tsx"]), [
    "src/index.tsx does not re-export the generated bindings",
    "src/index.tsx does not initialize the generated bindings",
  ]);
});

test("refuses an installRustCrate that registers nothing", () => {
  assert.deepEqual(glueProblems("cpp/kaleidoswap-swap-sdk.cpp", EMPTY["cpp/kaleidoswap-swap-sdk.cpp"]), [
    "cpp/kaleidoswap-swap-sdk.cpp does not register the native module in installRustCrate",
  ]);
});

test("refuses a CMakeLists that does not compile the generated C++", () => {
  assert.deepEqual(glueProblems("android/CMakeLists.txt", EMPTY["android/CMakeLists.txt"]), [
    "android/CMakeLists.txt does not compile the generated C++",
  ]);
});

test("accepts the re-export in either quote style, with or without a semicolon", () => {
  const index = LOADED["src/index.tsx"].replace(
    "export * from './generated/kaleidorg_swap_sdk';",
    'export * from "./generated/kaleidorg_swap_sdk"',
  );
  assert.deepEqual(glueProblems("src/index.tsx", index), []);
});

test("does not count a commented-out re-export", () => {
  const index = LOADED["src/index.tsx"].replace(
    "export * from './generated/kaleidorg_swap_sdk';",
    "// export * from './generated/kaleidorg_swap_sdk';",
  );
  assert.deepEqual(glueProblems("src/index.tsx", index), [
    "src/index.tsx does not re-export the generated bindings",
  ]);
});

test("does not accept a re-export of the low-level FFI module instead", () => {
  const index = LOADED["src/index.tsx"].replace(
    "export * from './generated/kaleidorg_swap_sdk';",
    "export * from './generated/kaleidorg_swap_sdk-ffi';",
  );
  assert.deepEqual(glueProblems("src/index.tsx", index), [
    "src/index.tsx does not re-export the generated bindings",
  ]);
});

test("names every failing file in one error, with the likely cause", () => {
  assert.throws(
    () => assertGlueLoadsCrate((path) => EMPTY[path]),
    (error) => {
      for (const path of Object.keys(EMPTY)) {
        assert.match(error.message, new RegExp(path.replace(/[.]/g, "\\.")));
      }
      assert.match(error.message, /does not load kaleidorg_swap_sdk/);
      assert.match(error.message, /not stripped/);
      return true;
    },
  );
});

test("refuses one bad file among good ones", () => {
  const files = { ...LOADED, "cpp/kaleidoswap-swap-sdk.cpp": EMPTY["cpp/kaleidoswap-swap-sdk.cpp"] };
  assert.throws(() => assertGlueLoadsCrate((path) => files[path]), /installRustCrate/);
});

test("has no checks for a file it was not told about", () => {
  assert.throws(() => glueProblems("src/arkade.ts", ""), /no checks for src\/arkade\.ts/);
});

test("prepack refuses to pack the 0.11.0 entry even with every file present", () => {
  const validate = join(dirname(fileURLToPath(import.meta.url)), "../scripts/validate-package.mjs");
  const root = mkdtempSync(join(tmpdir(), "rn-validate-"));
  try {
    const files = {
      ...EMPTY,
      "src/generated/kaleidorg_swap_sdk.ts": "",
      "react-native.config.js": "",
      "KaleidoswapSwapSdk.podspec": "",
      "cpp/generated/kaleidorg_swap_sdk.cpp": "",
    };
    for (const [path, source] of Object.entries(files)) {
      mkdirSync(dirname(join(root, path)), { recursive: true });
      writeFileSync(join(root, path), source);
    }
    const result = spawnSync(process.execPath, [validate], { cwd: root, encoding: "utf8" });
    assert.notEqual(result.status, 0);
    assert.match(result.stderr, /refusing to pack: the generated turbo module does not load kaleidorg_swap_sdk/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
